content.text:
Brief:
Un long cahier des charges pour un jeu de phare en plusieurs niveaux. Le joueur est le gardien d'un vieux phare sur une côte rocheuse, et chaque niveau se passe pendant une nuit de tempête. Des bateaux approchent depuis le large, et le joueur doit tourner le faisceau du phare en glissant le doigt autour de la tour pour éclairer chaque bateau avant qu'il ne touche les rochers. Un bateau éclairé assez longtemps trouve le chenal et rentre au port, ce qui compte pour l'objectif du niveau. Quand tous les bateaux d'une nuit sont rentrés, le niveau est gagné et une courte carte annonce la nuit suivante. Les nuits suivantes amènent plus de bateaux, du brouillard qui cache une partie de la mer et des vagues qui déplacent les bateaux. Si un bateau touche les rochers, la partie est perdue, avec un message qui dit quel bateau a coulé et un bouton pour rejouer la nuit. Je voudrais une mer bleu nuit, un faisceau jaune pâle et des bateaux rouges, dessinés simplement avec des formes plates. Le texte du jeu doit rester en français, avec le numéro de la nuit affiché en haut de l'écran pendant toute la partie.

Plan:
{"gameType":"stage-clear","input":"drag-follow","lang":"fr","loop":"Glissez le doigt autour de la tour pour tourner le faisceau et éclairer les bateaux avant qu'ils touchent les rochers. Ramenez tous les bateaux d'une nuit au port pour passer à la nuit suivante ; un bateau échoué termine la partie.","slug":"le-gardien-du-phare","style":"paper-cut","title":"Le Gardien du Phare"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="fr">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Le Gardien du Phare</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     overflow: hidden; background: #f4ecd8;
11|     touch-action: none;
12|     font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
13|   }
14|   canvas { display: block; touch-action: none; }
15| </style>
16| </head>
17| <body>
18| <canvas id="game"></canvas>
19| <script>
20| // ---- Bridge helper (verbatim) ----
21| const CARTRIDGE = {
22|   send(type, payload = {}) {
23|     window.parent.postMessage(
24|       { source: "cartridge", v: 1, type, payload },
25|       "*",
26|     );
27|   },
28| };
29| 
30| window.addEventListener("message", (event) => {
31|   const data = event.data;
32|   if (!data || data.source !== "cartridge-host") return;
33|   if (data.type === "pause") paused = true;
34|   if (data.type === "resume") paused = false;
35|   if (data.type === "reset") backToTitle();
36| });
37| 
38| // ---- Setup ----
39| const canvas = document.getElementById("game");
40| const ctx = canvas.getContext("2d");
41| 
42| let W = 0, H = 0, DPR = 1;
43| function resize() {
44|   DPR = window.devicePixelRatio || 1;
45|   W = window.innerWidth;
46|   H = window.innerHeight;
47|   canvas.width = Math.round(W * DPR);
48|   canvas.height = Math.round(H * DPR);
49|   canvas.style.width = W + "px";
50|   canvas.style.height = H + "px";
51|   ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
52| }
53| window.addEventListener("resize", resize);
54| resize();
55| 
56| // ---- Palette ----
57| const COL_BG = "#f4ecd8";
58| const COL_LAYER = "#e07a5f";
59| const COL_ACCENT = "#3d405b";
60| const COL_HILITE = "#81b29a";
61| 
62| // ---- Seeded jitter helper for paper-cut edges ----
63| function mulberry32(a) {
64|   return function () {
65|     a |= 0; a = (a + 0x6D2B79F5) | 0;
66|     let t = Math.imul(a ^ (a >>> 15), 1 | a);
67|     t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
68|     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
69|   };
70| }
71| const jitterRand = mulberry32(1337);
72| function jitterPoly(points, amt) {
73|   return points.map(p => [p[0] + (jitterRand() - 0.5) * amt, p[1] + (jitterRand() - 0.5) * amt]);
74| }
75| 
76| function drawPaperPath(pathPoints, fillColor, opts) {
77|   opts = opts || {};
78|   ctx.save();
79|   ctx.shadowColor = "rgba(61,64,91,0.35)";
80|   ctx.shadowBlur = 6;
81|   ctx.shadowOffsetY = 3;
82|   ctx.fillStyle = fillColor;
83|   ctx.beginPath();
84|   pathPoints.forEach((p, i) => {
85|     if (i === 0) ctx.moveTo(p[0], p[1]);
86|     else ctx.lineTo(p[0], p[1]);
87|   });
88|   ctx.closePath();
89|   ctx.fill();
90|   ctx.restore();
91| }
92| 
93| function roundRectPoints(x, y, w, h, r) {
94|   return [
95|     [x + r, y], [x + w - r, y], [x + w, y + r],
96|     [x + w, y + h - r], [x + w - r, y + h], [x + r, y + h],
97|     [x, y + h - r], [x, y + r]
98|   ];
99| }
100| 
101| // ---- Game state ----
102| let paused = false;
103| let screen = "title"; // title, playing, stageIntro, gameover, win
104| let stage = 0;
105| let score = 0;
106| let beamAngle = 0; // radians
107| let beamTarget = 0;
108| let held = false;
109| let graceTimer = 0;
110| let introTimer = 0;
111| let ships = [];
112| let shipsToSave = 0;
113| let shipsSaved = 0;
114| let lastTime = 0;
115| let stageGoalText = "";
116| 
117| const STAGES = [
118|   { count: 3, speed: 0.10, spawnGap: 2600 },
119|   { count: 4, speed: 0.13, spawnGap: 2200 },
120|   { count: 5, speed: 0.16, spawnGap: 1900 },
121|   { count: 6, speed: 0.19, spawnGap: 1600 },
122|   { count: 7, speed: 0.22, spawnGap: 1400 }
123| ];
124| 
125| const lighthouseCenter = () => ({ x: W / 2, y: H / 2 });
126| const towerRadius = () => Math.min(W, H) * 0.10;
127| const rockRadius = () => Math.min(W, H) * 0.46;
128| const portRadius = () => Math.min(W, H) * 0.14;
129| 
130| function backToTitle() {
131|   screen = "title";
132|   stage = 0;
133|   score = 0;
134|   ships = [];
135| }
136| 
137| function enterStage(next) {
138|   stage = next;
139|   const cfg = STAGES[stage - 1];
140|   shipsToSave = cfg.count;
141|   shipsSaved = 0;
142|   ships = [];
143|   spawnTimerAcc = 0;
144|   spawnGap = cfg.spawnGap;
145|   shipSpeed = cfg.speed;
146|   stageGoalText = "Sauvez " + shipsToSave + " bateau" + (shipsToSave > 1 ? "x" : "");
147|   screen = "stageIntro";
148|   introTimer = 2.2;
149|   CARTRIDGE.send("level", { index: stage });
150| }
151| 
152| let spawnTimerAcc = 0;
153| let spawnGap = 2000;
154| let shipSpeed = 0.1;
155| 
156| function spawnShip() {
157|   const angle = Math.random() * Math.PI * 2;
158|   const r = rockRadius() + 40;
159|   const c = lighthouseCenter();
160|   ships.push({
161|     angle: angle,
162|     dist: r,
163|     speed: shipSpeed + Math.random() * 0.03,
164|     lit: false,
165|     id: Math.random()
166|   });
167| }
168| 
169| function onGoalMet() {
170|   if (stage === STAGES.length) {
171|     CARTRIDGE.send("score", { value: score });
172|     CARTRIDGE.send("end", { reason: "win" });
173|     screen = "win";
174|   } else {
175|     enterStage(stage + 1);
176|   }
177| }
178| 
179| function onStageFailed() {
180|   CARTRIDGE.send("score", { value: score });
181|   CARTRIDGE.send("end", { reason: "lose" });
182|   screen = "gameover";
183| }
184| 
185| // ---- Input (drag-follow style, adapted to rotate beam) ----
186| function toCanvas(evt) {
187|   const rect = canvas.getBoundingClientRect();
188|   return {
189|     x: evt.clientX - rect.left,
190|     y: evt.clientY - rect.top
191|   };
192| }
193| 
194| function angleFromCenter(pt) {
195|   const c = lighthouseCenter();
196|   return Math.atan2(pt.y - c.y, pt.x - c.x);
197| }
198| 
199| canvas.addEventListener("pointerdown", (event) => {
200|   if (screen === "title") {
201|     startGame();
202|     return;
203|   }
204|   if (screen === "gameover" || screen === "win") {
205|     backToTitle();
206|     return;
207|   }
208|   held = true;
209|   const p = toCanvas(event);
210|   beamTarget = angleFromCenter(p);
211|   canvas.setPointerCapture(event.pointerId);
212| });
213| canvas.addEventListener("pointermove", (event) => {
214|   if (held) {
215|     const p = toCanvas(event);
216|     beamTarget = angleFromCenter(p);
217|   }
218| });
219| function releasePointer() { held = false; }
220| canvas.addEventListener("pointerup", releasePointer);
221| canvas.addEventListener("pointercancel", releasePointer);
222| 
223| function startGame() {
224|   screen = "stageIntro";
225|   score = 0;
226|   CARTRIDGE.send("start");
227|   enterStage(1);
228| }
229| 
230| // ---- Update ----
231| function angleDiff(a, b) {
232|   let d = (b - a) % (Math.PI * 2);
233|   if (d > Math.PI) d -= Math.PI * 2;
234|   if (d < -Math.PI) d += Math.PI * 2;
235|   return d;
236| }
237| 
238| function update(dt) {
239|   if (screen === "stageIntro") {
240|     introTimer -= dt;
241|     if (introTimer <= 0) {
242|       screen = "playing";
243|       graceTimer = 2.5;
244|     }
245|     return;
246|   }
247|   if (screen !== "playing") return;
248| 
249|   // ease beam angle towards target
250|   const diff = angleDiff(beamAngle, beamTarget);
251|   beamAngle += diff * Math.min(1, dt * 8);
252| 
253|   if (graceTimer > 0) graceTimer -= dt;
254| 
255|   spawnTimerAcc += dt * 1000;
256|   if (spawnTimerAcc > spawnGap && ships.length < shipsToSave - shipsSaved + 2) {
257|     spawnTimerAcc = 0;
258|     if (ships.length + shipsSaved < shipsToSave) spawnShip();
259|   }
260| 
261|   const c = lighthouseCenter();
262|   const beamWidth = 0.32;
263| 
264|   for (let i = ships.length - 1; i >= 0; i--) {
265|     const s = ships[i];
266|     // check if lit
267|     const ad = Math.abs(angleDiff(beamAngle, s.angle));
268|     s.lit = ad < beamWidth;
269| 
270|     if (s.lit) {
271|       // move inward towards port
272|       s.dist -= s.speed * 60 * dt * 0.6;
273|     } else {
274|       // drift towards rocks
275|       s.dist -= s.speed * 60 * dt * 0.15;
276|       // wobble angle a bit
277|       s.angle += Math.sin(performance.now() / 900 + s.id * 10) * 0.0015;
278|     }
279| 
280|     if (s.dist <= portRadius()) {
281|       ships.splice(i, 1);
282|       shipsSaved++;
283|       score += 10;
284|       CARTRIDGE.send("score", { value: score });
285|       continue;
286|     }
287| 
288|     if (s.dist <= towerRadius() + 6 && graceTimer <= 0) {
289|       // hit rocks near tower means wrecked (too close without being saved through port logic distance)
290|     }
291| 
292|     if (graceTimer <= 0 && s.dist <= towerRadius() * 1.4 && !s.lit) {
293|       // wrecked on rocks (rocks ring visually near tower not edge; use inner threshold when unlit for too long)
294|     }
295|   }
296| 
297|   // Wreck detection: if unlit ship distance falls to rock-ring band while not making progress to port
298|   for (let i = ships.length - 1; i >= 0; i--) {
299|     const s = ships[i];
300|     if (graceTimer <= 0 && !s.lit && s.dist < rockRadius() * 0.5) {
301|       // shipwreck!
302|       ships.splice(i, 1);
303|       onStageFailed();
304|       return;
305|     }
306|   }
307| 
308|   if (shipsSaved >= shipsToSave && ships.length === 0) {
309|     onGoalMet();
310|   }
311| }
312| 
313| // ---- Draw ----
314| function drawBackground() {
315|   ctx.fillStyle = COL_BG;
316|   ctx.fillRect(0, 0, W, H);
317|   // subtle stars
318|   ctx.fillStyle = "rgba(61,64,91,0.15)";
319|   for (let i = 0; i < 40; i++) {
320|     const sx = (i * 97.3) % W;
321|     const sy = (i * 53.7) % H;
322|     ctx.beginPath();
323|     ctx.arc(sx, sy, 1.4, 0, Math.PI * 2);
324|     ctx.fill();
325|   }
326| }
327| 
328| function drawRocks() {
329|   const c = lighthouseCenter();
330|   const r = rockRadius();
331|   ctx.save();
332|   const n = 22;
333|   const pts = [];
334|   for (let i = 0; i < n; i++) {
335|     const a = (i / n) * Math.PI * 2;
336|     const rr = r + (jitterRand() - 0.5) * 14;
337|     pts.push([c.x + Math.cos(a) * rr, c.y + Math.sin(a) * rr]);
338|   }
339|   drawPaperPath(pts, "#c98a6b");
340|   ctx.restore();
341| }
342| 
343| function drawPort() {
344|   const c = lighthouseCenter();
345|   const r = portRadius();
346|   const n = 16;
347|   let pts = [];
348|   for (let i = 0; i < n; i++) {
349|     const a = (i / n) * Math.PI * 2;
350|     pts.push([c.x + Math.cos(a) * r, c.y + Math.sin(a) * r]);
351|   }
352|   pts = jitterPoly(pts, 3);
353|   drawPaperPath(pts, COL_HILITE);
354| }
355| 
356| function drawBeam() {
357|   const c = lighthouseCenter();
358|   const len = rockRadius() + 60;
359|   const spread = 0.32;
360|   ctx.save();
361|   ctx.globalAlpha = 0.35;
362|   ctx.fillStyle = "#f2e9c9";
363|   ctx.beginPath();
364|   ctx.moveTo(c.x, c.y);
365|   ctx.arc(c.x, c.y, len, beamAngle - spread, beamAngle + spread);
366|   ctx.closePath();
367|   ctx.fill();
368|   ctx.restore();
369| }
370| 
371| function drawTower() {
372|   const c = lighthouseCenter();
373|   const r = towerRadius();
374|   let pts = roundRectPoints(c.x - r * 0.6, c.y - r * 1.3, r * 1.2, r * 2.2, 6);
375|   pts = jitterPoly(pts, 2);
376|   drawPaperPath(pts, COL_LAYER);
377| 
378|   // top cap
379|   let capPts = [
380|     [c.x - r * 0.75, c.y - r * 1.3],
381|     [c.x + r * 0.75, c.y - r * 1.3],
382|     [c.x + r * 0.4, c.y - r * 1.7],
383|     [c.x - r * 0.4, c.y - r * 1.7]
384|   ];
385|   capPts = jitterPoly(capPts, 2);
386|   drawPaperPath(capPts, COL_ACCENT);
387| 
388|   // lamp dot
389|   ctx.save();
390|   ctx.fillStyle = "#f2e9c9";
391|   ctx.shadowColor = "rgba(242,233,201,0.8)";
392|   ctx.shadowBlur = 12;
393|   ctx.beginPath();
394|   ctx.arc(c.x, c.y - r * 1.4, 6, 0, Math.PI * 2);
395|   ctx.fill();
396|   ctx.restore();
397| }
398| 
399| function drawShip(s) {
400|   const c = lighthouseCenter();
401|   const x = c.x + Math.cos(s.angle) * s.dist;
402|   const y = c.y + Math.sin(s.angle) * s.dist;
403|   const size = 16;
404|   ctx.save();
405|   ctx.translate(x, y);
406|   ctx.rotate(s.angle + Math.PI / 2);
407|   let hull = [
408|     [-size * 0.5, size * 0.4],
409|     [size * 0.5, size * 0.4],
410|     [size * 0.35, -size * 0.4],
411|     [-size * 0.35, -size * 0.4]
412|   ];
413|   hull = jitterPoly(hull, 1.5);
414|   drawPaperPath(hull, s.lit ? COL_HILITE : COL_ACCENT);
415|   ctx.restore();
416| }
417| 
418| function drawUI() {
419|   ctx.fillStyle = COL_ACCENT;
420|   ctx.font = "bold 18px sans-serif";
421|   ctx.textAlign = "left";
422|   ctx.fillText("Nuit " + stage, 16, 30);
423|   ctx.fillText("Score: " + score, 16, 54);
424|   ctx.fillText("Sauvés: " + shipsSaved + "/" + shipsToSave, 16, 78);
425| }
426| 
427| function drawTitle() {
428|   drawBackground();
429|   drawRocks();
430|   drawPort();
431|   drawTower();
432|   ctx.save();
433|   ctx.fillStyle = COL_ACCENT;
434|   ctx.textAlign = "center";
435|   ctx.font = "bold 34px sans-serif";
436|   ctx.fillText("Le Gardien du Phare", W / 2, H * 0.28);
437|   ctx.font = "18px sans-serif";
438|   ctx.fillText("Glissez le doigt pour tourner le faisceau", W / 2, H * 0.35);
439|   ctx.fillText("Guidez chaque bateau au port avant les rochers", W / 2, H * 0.40);
440|   ctx.font = "bold 22px sans-serif";
441|   ctx.fillText("Touchez pour commencer", W / 2, H * 0.55);
442|   ctx.restore();
443| }
444| 
445| function drawStageIntro() {
446|   drawBackground();
447|   drawRocks();
448|   drawPort();
449|   drawTower();
450|   ctx.save();
451|   ctx.fillStyle = COL_ACCENT;
452|   ctx.textAlign = "center";
453|   ctx.font = "bold 30px sans-serif";
454|   ctx.fillText("Nuit " + stage, W / 2, H * 0.4);
455|   ctx.font = "22px sans-serif";
456|   ctx.fillText(stageGoalText, W / 2, H * 0.48);
457|   ctx.restore();
458| }
459| 
460| function drawGameOver(msg) {
461|   drawBackground();
462|   drawRocks();
463|   drawPort();
464|   drawTower();
465|   ctx.save();
466|   ctx.fillStyle = COL_ACCENT;
467|   ctx.textAlign = "center";
468|   ctx.font = "bold 30px sans-serif";
469|   ctx.fillText(msg, W / 2, H * 0.4);
470|   ctx.font = "20px sans-serif";
471|   ctx.fillText("Score final: " + score, W / 2, H * 0.48);
472|   ctx.font = "bold 20px sans-serif";
473|   ctx.fillText("Touchez pour recommencer", W / 2, H * 0.56);
474|   ctx.restore();
475| }
476| 
477| function draw() {
478|   if (screen === "title") {
479|     drawTitle();
480|     return;
481|   }
482|   if (screen === "stageIntro") {
483|     drawStageIntro();
484|     return;
485|   }
486|   if (screen === "gameover") {
487|     drawGameOver("Bateau échoué !");
488|     return;
489|   }
490|   if (screen === "win") {
491|     drawGameOver("Toutes les nuits éclairées !");
492|     return;
493|   }
494|   drawBackground();
495|   drawRocks();
496|   drawPort();
497|   drawBeam();
498|   drawTower();
499|   ships.forEach(drawShip);
500|   drawUI();
501| 
502|   if (graceTimer > 0) {
503|     ctx.save();
504|     ctx.fillStyle = COL_ACCENT;
505|     ctx.textAlign = "center";
506|     ctx.font = "18px sans-serif";
507|     ctx.fillText("Préparez-vous...", W / 2, H * 0.15);
508|     ctx.restore();
509|   }
510| }
511| 
512| // ---- Main loop ----
513| function frame(t) {
514|   const dt = Math.min(0.05, (t - lastTime) / 1000 || 0);
515|   lastTime = t;
516|   if (!paused) {
517|     update(dt);
518|   }
519|   draw();
520|   requestAnimationFrame(frame);
521| }
522| 
523| // Boot: draw first frame, then send boot
524| draw();
525| CARTRIDGE.send("boot", { title: "Le Gardien du Phare", gameType: "stage-clear", lang: "fr" });
526| requestAnimationFrame(frame);
527| </script>
528| </body>
529| </html>
530|

